def _find(self, label):
    if self.label == label:
        return self
    for child in self.children:
        found = child._find(label)
        if found is not None:
            return found
    return None

def _reorient(self, node):
    if self.label == node:
        return self
    for child in self.children:
        rerooted = child._reorient(node)
        if rerooted is not None:
            self.children.remove(child)
            rerooted.children.append(self)
            return rerooted
    return None

def from_pov(self, from_node):
    rerooted = self._reorient(from_node)
    if rerooted is None:
        raise ValueError("Tree could not be reoriented")
    return rerooted

def _path(self, to_node):
    if self.label == to_node:
        return [self.label]
    for child in self.children:
        path = child._path(to_node)
        if path is not None:
            return [self.label] + path
    return None

def path_to(self, from_node, to_node):
    rerooted = self.from_pov(from_node)
    path = rerooted._path(to_node)
    if path is None:
        raise ValueError("No path found")
    return path

